// Countries and their flags, for fantasy races and made-up drivers (real drivers do not get a nationality here).
export const COUNTRIES = [['Australia', '🇦🇺'], ['Austria', '🇦🇹'], ['Azerbaijan', '🇦🇿'], ['Bahrain', '🇧🇭'], ['Belgium', '🇧🇪'], ['Brazil', '🇧🇷'], ['Canada', '🇨🇦'], ['China', '🇨🇳'], ['Denmark', '🇩🇰'], ['Finland', '🇫🇮'], ['France', '🇫🇷'], ['Germany', '🇩🇪'], ['Greece', '🇬🇷'], ['Hungary', '🇭🇺'], ['India', '🇮🇳'], ['Ireland', '🇮🇪'], ['Italy', '🇮🇹'], ['Japan', '🇯🇵'], ['Malaysia', '🇲🇾'], ['Mexico', '🇲🇽'], ['Monaco', '🇲🇨'], ['Netherlands', '🇳🇱'], ['New Zealand', '🇳🇿'], ['Norway', '🇳🇴'], ['Poland', '🇵🇱'], ['Portugal', '🇵🇹'], ['Qatar', '🇶🇦'], ['Saudi Arabia', '🇸🇦'], ['Singapore', '🇸🇬'], ['South Africa', '🇿🇦'], ['Spain', '🇪🇸'], ['Sweden', '🇸🇪'], ['Switzerland', '🇨🇭'], ['Thailand', '🇹🇭'], ['Turkey', '🇹🇷'], ['UAE', '🇦🇪'], ['United Kingdom', '🇬🇧'], ['USA', '🇺🇸'], ['Argentina', '🇦🇷'], ['Colombia', '🇨🇴'], ['Czechia', '🇨🇿'], ['Estonia', '🇪🇪'], ['Indonesia', '🇮🇩'], ['Israel', '🇮🇱'], ['Russia', '🇷🇺'], ['Venezuela', '🇻🇪']];
const ALIAS = { 'united states': 'USA', 'united states of america': 'USA', 'uk': 'United Kingdom', 'england': 'United Kingdom', 'great britain': 'United Kingdom', 'united arab emirates': 'UAE', 'abu dhabi': 'UAE', 'las vegas': 'USA', 'miami': 'USA', 'austin': 'USA', 'texas': 'USA', 'usa': 'USA' };
const FLAGS = Object.fromEntries(COUNTRIES.map(([n, f]) => [n.toLowerCase(), f]));
export const countryNames = COUNTRIES.map(([n]) => n);
export const flagOfCountry = (name) => { const k = String(name || '').trim().toLowerCase(); return FLAGS[ALIAS[k] ? ALIAS[k].toLowerCase() : k] || ''; };
// "Melbourne, Australia" -> 🇦🇺 (the last part of the place)
export const flagOfPlace = (place) => { const parts = String(place || '').split(',').map((x) => x.trim()).filter(Boolean); for (let i = parts.length - 1; i >= 0; i--) { const f = flagOfCountry(parts[i]); if (f) return f; } return ''; };
export const randomCountry = () => { const w = ['United Kingdom', 'Italy', 'Spain', 'France', 'Germany', 'Netherlands', 'Brazil', 'Japan', 'Australia', 'Finland', 'Denmark', 'USA', 'Canada', 'Mexico', 'Poland', 'Sweden', 'Switzerland', 'Argentina', 'Thailand', 'Greece']; return w[Math.floor(Math.random() * w.length)]; };
